# 20_splits.R: split-to-split variability of the conditional contrasts and compensation (30 random 70/30 site splits of revision_random/tables/random_splits.csv; shared and full pools).
# For every split the support machinery, the combinations (training sites only) and both coherent models are rebuilt from the TRAINING sites; contrasts are evaluated only where the all-site matched interval is supported by the training sites of that split
# (otherwise the split is recorded as unavailable and no comparison is forced). Held-out D2 (test sites, training basis) of the spread-only and additive models is reported for total, occupancy-associated and heterogeneity components.
# Usage (final/, ZG_LIB6 = principal package library): NCORES=9 Rscript revision_fig6/20_splits.R
source("revision_fig6/00_fig6_common.R"); NC <- as.integer(Sys.getenv("NCORES", "9")); OUTT <- "revision_fig6/tables"; SUPS <- read.csv(file.path(OUTT, "fig6_support_summary.csv")); SPL <- read.csv("revision_random/tables/random_splits.csv", stringsAsFactors = FALSE); NS <- max(SPL$split)
tmpdir <- tempfile("sup"); dir.create(tmpdir); OUT <- tmpdir
one <- function(job) { pool <- job$pool; sp <- job$split; res <- list(); ho <- list(); OUT <<- file.path(tempdir(), paste0("s", Sys.getpid())); dir.create(OUT, FALSE, TRUE)
  for (tx in names(ORD)) for (k in ORD[[tx]]) { d <- get_d(pool, tx); z <- SPL[SPL$pool == pool & SPL$community == TXL[[tx]] & SPL$split == sp, ]; role <- setNames(z$role, z$site_id)[d$env$id]; tr <- which(role == "train"); te <- which(role == "test")
    iv <- SUPS$matched_interval[SUPS$pool == pool & SUPS$group == tx & SUPS$order == k]; avail_all <- SUPS$matched_available[SUPS$pool == pool & SUPS$group == tx & SUPS$order == k]; base <- data.frame(pool = pool, split = sp, group = tx, order = k, n_train_sites = length(tr), n_test_sites = length(te), all_site_interval_available = avail_all)
    if (!isTRUE(avail_all)) { res[[length(res) + 1]] <- cbind(base, available = FALSE, reason = "no common support in the all-site analysis"); next }
    dtr <- list(x = d$x[tr, , drop = FALSE], env = d$env[tr, , drop = FALSE]); p <- tryCatch(prepare(paste0(pool, "_s", sp), tx, k, dtr), error = function(e) NULL)
    if (is.null(p)) { res[[length(res) + 1]] <- cbind(base, available = FALSE, reason = "support screening failed"); next }
    y <- ugdm_component_response(dtr$x, p$dd$idx); dd <- list(additive = p$dd, spread_only = ugdm_component_design(p$E, p$dd$idx, "spread_only", coordinates = p$xy, lonlat = TRUE)); fits <- lapply(dd, function(q) ugdm_fit_components(q, y, "coherent"))
    # held-out predictive performance (test sites; training basis)
    il_te <- sample_sets(length(te), k, 3000, seed = 200000L + 1000L * sp + k); Ete <- data.frame(TP = log10(d$env$TP[te]), TN = log10(d$env$TN[te]), Chla = log10(d$env$Chla[te])); xyte <- as.matrix(d$env[te, c("lon", "lat")]); v <- ugdm_component_response(d$x[te, , drop = FALSE], il_te)
    for (m in names(fits)) { dte <- ugdm_component_design(Ete, il_te, m, coordinates = xyte, lonlat = TRUE, reference = dd[[m]]); a <- ugdm_assess_components(fits[[m]], dte, v, y); ho[[length(ho) + 1]] <- cbind(base, model = m, a$metrics[, intersect(c("component", "D2", "RMSE", "bias"), names(a$metrics))], converged = fits[[m]]$converged, closure_RMSE = a$closure_RMSE) }
    if (!(iv %in% names(p$valid))) { res[[length(res) + 1]] <- cbind(base, available = FALSE, reason = "matched interval not supported by training sites"); next }
    ij <- parse_iv(iv); svals <- GRID[ij[1]:ij[2]]; ids <- select_ids(p$valid[[iv]], 120L); s_lo <- svals[1]; s_hi <- svals[length(svals)]; s_mid <- svals[ceiling(length(svals) / 2)]; G <- list()
    for (m in names(fits)) { bT <- setNames(bvec(fits[[m]], "total"), colnames(layoutfn(dd[[m]], TRUE)$X)); bS <- setNames(bvec(fits[[m]], "share"), names(bT)); for (pn in names(PCOL)) for (sv in unique(c(s_lo, s_mid, s_hi))) G[[paste(m, pn, sv)]] <- cell_parts(p, dd[[m]], m, ids, log10(PCOL[[pn]]), sv, bT, bS) }
    for (m in names(fits)) { for (pn in names(PCOL)) { ca <- contrast_A(G, m, pn, s_lo, s_hi); res[[length(res) + 1]] <- cbind(base, available = TRUE, reason = "", contrast = "A_spread", ca[, c("model", "position", "s_from", "s_to", "n_profiles", "dT_pp", "dO_pp", "dH_pp")], comp_measures(ca$dT_pp, ca$dO_pp, ca$dH_pp)) }
      cb <- contrast_B(G, m, "Low", "High", s_mid); res[[length(res) + 1]] <- cbind(base, available = TRUE, reason = "", contrast = "B_position_low_to_high", model = m, position = "Low->High", s_from = s_mid, s_to = s_mid, n_profiles = cb$n_profiles, dT_pp = cb$dT_pp, dO_pp = cb$dO_pp, dH_pp = cb$dH_pp, comp_measures(cb$dT_pp, cb$dO_pp, cb$dH_pp), explicit_position_dT = cb$explicit_position_dT, spline_slope_dT = cb$spline_slope_dT) } }
  list(r = bind_rows(res), h = bind_rows(ho)) }
jobs <- do.call(c, lapply(POOLSET, function(p) lapply(seq_len(NS), function(s) list(pool = p, split = s)))); if (nzchar(Sys.getenv("ONLY"))) jobs <- jobs[as.integer(strsplit(Sys.getenv("ONLY"), ",")[[1]])]; t0 <- Sys.time(); RES <- mclapply(jobs, function(j) tryCatch(one(j), error = function(e) { message("ERR ", j$pool, " ", j$split, ": ", conditionMessage(e)); NULL }), mc.cores = NC, mc.preschedule = FALSE); cat("elapsed", format(Sys.time() - t0), "bad", sum(vapply(RES, is.null, TRUE)), "\n")
R <- bind_rows(lapply(RES, function(x) if (!is.null(x)) x$r)); H <- bind_rows(lapply(RES, function(x) if (!is.null(x)) x$h)); sfx <- if (nzchar(Sys.getenv("ONLY"))) "_test" else ""; write.csv(R, file.path(OUTT, sprintf("fig6_splits_contrasts%s.csv", sfx)), row.names = FALSE); write.csv(H, file.path(OUTT, sprintf("fig6_splits_heldout%s.csv", sfx)), row.names = FALSE); cat("rows", nrow(R), nrow(H), "\n")
